-- =============================================================================
-- DEYNOLD DANNY — Migration 0007
-- Upgrades Legal Policies (Privacy Policy, Shipping & Returns, Terms & Conditions,
-- Cookie Policy) to comprehensive Indian & international legal standards
-- (DPDP Act 2023, Consumer Protection E-Commerce Rules 2020, GDPR/UK-GDPR/CCPA,
-- Multi-Currency Display vs INR Settlement, International Express Shipping)
-- and adds editable "The House / About Us" CMS page (`page_about`).
-- =============================================================================

PRAGMA foreign_keys = ON;

-- 1. Seed The House / About Us system page
INSERT OR IGNORE INTO cms_pages (
  id, slug, route_path, page_type, title, status, template_key, is_system_route,
  draft_seo_json, published_seo_json, updated_by
) VALUES (
  'page_about',
  'about',
  '/about',
  'custom',
  'The House of Deynold Danny',
  'published',
  'legal',
  1,
  '{"title":"The House of Deynold Danny | Artisanal Luxury Tailoring — Made in India","description":"Discover the heritage, architectural tailoring, noble natural fibers, and New Delhi flagship atelier of DEYNOLD DANNY."}',
  '{"title":"The House of Deynold Danny | Artisanal Luxury Tailoring — Made in India","description":"Discover the heritage, architectural tailoring, noble natural fibers, and New Delhi flagship atelier of DEYNOLD DANNY."}',
  'system'
);

INSERT OR IGNORE INTO cms_sections (
  id, page_id, section_key, section_type, title, sort_order,
  is_draft_visible, is_published_visible, status, draft_props_json, published_props_json
) VALUES (
  'sec_about_house_body',
  'page_about',
  'about-body',
  'legal_document',
  'The House Narrative',
  1, 1, 1, 'published',
  '{"eyebrow":"THE HOUSE • EST. NEW DELHI","heading":"The House of Deynold Danny","effectiveDate":"Handcrafted in India • Dispatched Worldwide","sections":[{"heading":"1. Architectural Quiet Luxury","body":"Founded in New Delhi, DEYNOLD DANNY is a contemporary luxury fashion house devoted to architectural restraint, enduring proportion, and tactile excellence. Every garment is conceived to outlast seasonal noise—engineered around clean shoulder geometry, fluid drape, and understated permanence."},{"heading":"2. Noble Fibers & Material Provenance","body":"We partner exclusively with certified heritage mills and responsible raw-fiber producers to source extra-fine virgin wool, Grade-A inner-fleece cashmere, long-staple Egyptian cotton poplin, mulberry silk, and full-grain vegetable-tanned calfskin. Each cloth is inspected by hand prior to pattern cutting for tensile recovery, breathability, and lustre."},{"heading":"3. Artisanal Indian Craftsmanship","body":"Every piece is cut, canvas-structured, hand-finished, and quality-certified in India by master tailors and patternmakers. From horn buttons stitched with waxed thread to balanced hand-pressed seams and breathable Bemberg cupro linings, each silhouette carries the quiet discipline of true atelier construction."},{"heading":"4. Responsible Small-Batch Production","body":"Rather than overproducing for clearance cycles, DEYNOLD DANNY crafts garments in numbered small batches aligned with patron demand. Our archival keepsake packaging uses FSC-certified rigid board, acid-free tissue, and reusable cotton garment covers designed for decades of wardrobe stewardship."},{"heading":"5. Global Patronage & Private Client Services","body":"From our New Delhi flagship atelier, we serve patrons across India, the United States, the United Kingdom, the European Union, the United Arab Emirates, Singapore, Australia, Canada, Switzerland, Japan, Saudi Arabia, and Qatar with insured international express logistics and personal sizing consultation."}]}',
  '{"eyebrow":"THE HOUSE • EST. NEW DELHI","heading":"The House of Deynold Danny","effectiveDate":"Handcrafted in India • Dispatched Worldwide","sections":[{"heading":"1. Architectural Quiet Luxury","body":"Founded in New Delhi, DEYNOLD DANNY is a contemporary luxury fashion house devoted to architectural restraint, enduring proportion, and tactile excellence. Every garment is conceived to outlast seasonal noise—engineered around clean shoulder geometry, fluid drape, and understated permanence."},{"heading":"2. Noble Fibers & Material Provenance","body":"We partner exclusively with certified heritage mills and responsible raw-fiber producers to source extra-fine virgin wool, Grade-A inner-fleece cashmere, long-staple Egyptian cotton poplin, mulberry silk, and full-grain vegetable-tanned calfskin. Each cloth is inspected by hand prior to pattern cutting for tensile recovery, breathability, and lustre."},{"heading":"3. Artisanal Indian Craftsmanship","body":"Every piece is cut, canvas-structured, hand-finished, and quality-certified in India by master tailors and patternmakers. From horn buttons stitched with waxed thread to balanced hand-pressed seams and breathable Bemberg cupro linings, each silhouette carries the quiet discipline of true atelier construction."},{"heading":"4. Responsible Small-Batch Production","body":"Rather than overproducing for clearance cycles, DEYNOLD DANNY crafts garments in numbered small batches aligned with patron demand. Our archival keepsake packaging uses FSC-certified rigid board, acid-free tissue, and reusable cotton garment covers designed for decades of wardrobe stewardship."},{"heading":"5. Global Patronage & Private Client Services","body":"From our New Delhi flagship atelier, we serve patrons across India, the United States, the United Kingdom, the European Union, the United Arab Emirates, Singapore, Australia, Canada, Switzerland, Japan, Saudi Arabia, and Qatar with insured international express logistics and personal sizing consultation."}]}'
);

-- 2. Upgrade Privacy Policy (DPDP Act 2023 + GDPR/UK-GDPR/CCPA)
UPDATE cms_sections
SET
  draft_props_json = '{"eyebrow":"LEGAL GOVERNANCE & DATA PROTECTION","heading":"Privacy & Data Protection Policy","effectiveDate":"Effective: November 2026 · Compliant with India DPDP Act 2023, GDPR & CCPA","sections":[{"heading":"1. Data Fiduciary & Scope","body":"DEYNOLD DANNY Atelier Pvt. Ltd. (\"DEYNOLD DANNY\", \"the House\", \"we\", \"our\") acts as the Data Fiduciary under India''s Digital Personal Data Protection Act, 2023 (DPDP Act) and as Data Controller for international patrons under the EU/UK General Data Protection Regulation (GDPR) and California Consumer Privacy Act (CCPA/CPRA). This Policy explains how we collect, use, secure, retain, and delete personal data across our digital flagship, private client portal, and concierge channels."},{"heading":"2. Personal Data We Collect","body":"We collect only data strictly necessary for luxury retail operations and client service: (a) Identity & Contact Data: full name, email address, telephone number, and billing/shipping addresses; (b) Transactional & Tax Data: order references, SKU selections, GST invoice details, return/exchange records, and statutory PAN information where mandated by Indian tax law for high-value orders; (c) Fit & Styling Data: optional garment measurements or Fit Finder inputs you provide; (d) Technical & Security Data: anonymized session identifiers, anti-fraud rate-limiting metadata, and consent records."},{"heading":"3. Lawful Basis & Purpose of Processing","body":"We process personal data strictly on verifiable lawful grounds: (a) Contractual Necessity — authenticating passwordless OTP sessions, reserving inventory, fulfilling orders, issuing GST invoices, processing returns/refunds, and delivering shipments; (b) Legal Obligation — complying with the GST Act, Income Tax Act, RBI payment directives, and Consumer Protection (E-Commerce) Rules, 2020; (c) Explicit Opt-In Consent — optional storefront analytics, restock alerts, and editorial newsletters, which remain disabled until you affirmatively opt in."},{"heading":"4. Passwordless Authentication & Payment Security","body":"DEYNOLD DANNY uses one-time cryptographic email verification codes (OTP) rather than stored reusable passwords. Active sessions rely on short-lived memory-only access tokens paired with HttpOnly, Secure, SameSite cookies that cannot be read by client-side scripts. All payment transactions are processed exclusively through PCI-DSS Level 1 certified gateways (Razorpay and Cashfree). We never capture, transmit, or store raw credit/debit card numbers, CVV codes, UPI PINs, or net-banking credentials."},{"heading":"5. Trusted Data Processors & Logistics Partners","body":"We never sell, rent, or trade client personal data. We share strictly limited operational fields solely with vetted processors bound by confidentiality agreements: payment gateways (Razorpay, Cashfree) for payment authorization and refunds; domestic and international courier partners (Shiprocket, Blue Dart, DHL Express, FedEx) for insured delivery and customs clearance; transactional email infrastructure (Resend) for OTP codes and order milestones; and Cloudflare edge infrastructure for DDoS mitigation and encrypted database storage."},{"heading":"6. International Cross-Border Data Transfers","body":"Because DEYNOLD DANNY serves global patrons across India, North America, Europe, the Middle East, and Asia-Pacific, your data may be processed on encrypted Cloudflare global edge nodes and transferred to destination customs authorities solely to clear international deliveries. All cross-border transfers adhere to DPDP Act Section 16 notifications and EU Standard Contractual Clauses (SCCs) with TLS 1.3 encryption in transit."},{"heading":"7. Data Retention & Statutory Archival","body":"Account profiles and saved addresses are retained while your client account remains active. One-time verification codes expire within 10 minutes and are purged automatically. Order invoices, tax ledgers, and payment audit logs are retained for the statutory period mandated under Indian GST and Companies Act regulations (typically 8 financial years), after which personal identifiers are anonymized or destroyed."},{"heading":"8. Your Rights as a Data Principal / Client","body":"Under the DPDP Act 2023, GDPR, and CCPA, you hold the right to: (a) Access & Portability — export a complete machine-readable JSON archive of your account data directly from your Private Client Portal; (b) Correction & Updating — update inaccurate profile or address information at any time; (c) Erasure & Anonymization — request permanent account erasure/anonymization directly inside your Account Portal (once no active unfulfilled orders or open disputes remain); (d) Withdraw Consent — adjust cookie, analytics, or newsletter permissions at any time with zero service penalty; (e) Nominate — designate a representative under DPDP Section 14 to exercise your rights in the event of incapacity."},{"heading":"9. Protection of Minors","body":"Our digital flagship is intended exclusively for individuals aged 18 years or older (or the age of legal majority in your jurisdiction). We do not knowingly collect personal data from children under 18. If a parent or guardian believes a minor has provided personal information, contact our Data Protection Officer immediately for prompt deletion."},{"heading":"10. Data Protection & Grievance Redressal Officer","body":"In compliance with the DPDP Act 2023 and the Consumer Protection (E-Commerce) Rules, 2020, any privacy inquiry, data request, or grievance may be addressed to our Data Protection & Grievance Officer: Email: privacy@deynolddanny.com | Concierge Desk: +91 11 4820 9000 (Mon–Sat, 10:00–19:00 IST) | Address: DEYNOLD DANNY Atelier Pvt. Ltd., New Delhi, India. All grievances are acknowledged within 48 hours and resolved within 30 calendar days."}]}',
  published_props_json = '{"eyebrow":"LEGAL GOVERNANCE & DATA PROTECTION","heading":"Privacy & Data Protection Policy","effectiveDate":"Effective: November 2026 · Compliant with India DPDP Act 2023, GDPR & CCPA","sections":[{"heading":"1. Data Fiduciary & Scope","body":"DEYNOLD DANNY Atelier Pvt. Ltd. (\"DEYNOLD DANNY\", \"the House\", \"we\", \"our\") acts as the Data Fiduciary under India''s Digital Personal Data Protection Act, 2023 (DPDP Act) and as Data Controller for international patrons under the EU/UK General Data Protection Regulation (GDPR) and California Consumer Privacy Act (CCPA/CPRA). This Policy explains how we collect, use, secure, retain, and delete personal data across our digital flagship, private client portal, and concierge channels."},{"heading":"2. Personal Data We Collect","body":"We collect only data strictly necessary for luxury retail operations and client service: (a) Identity & Contact Data: full name, email address, telephone number, and billing/shipping addresses; (b) Transactional & Tax Data: order references, SKU selections, GST invoice details, return/exchange records, and statutory PAN information where mandated by Indian tax law for high-value orders; (c) Fit & Styling Data: optional garment measurements or Fit Finder inputs you provide; (d) Technical & Security Data: anonymized session identifiers, anti-fraud rate-limiting metadata, and consent records."},{"heading":"3. Lawful Basis & Purpose of Processing","body":"We process personal data strictly on verifiable lawful grounds: (a) Contractual Necessity — authenticating passwordless OTP sessions, reserving inventory, fulfilling orders, issuing GST invoices, processing returns/refunds, and delivering shipments; (b) Legal Obligation — complying with the GST Act, Income Tax Act, RBI payment directives, and Consumer Protection (E-Commerce) Rules, 2020; (c) Explicit Opt-In Consent — optional storefront analytics, restock alerts, and editorial newsletters, which remain disabled until you affirmatively opt in."},{"heading":"4. Passwordless Authentication & Payment Security","body":"DEYNOLD DANNY uses one-time cryptographic email verification codes (OTP) rather than stored reusable passwords. Active sessions rely on short-lived memory-only access tokens paired with HttpOnly, Secure, SameSite cookies that cannot be read by client-side scripts. All payment transactions are processed exclusively through PCI-DSS Level 1 certified gateways (Razorpay and Cashfree). We never capture, transmit, or store raw credit/debit card numbers, CVV codes, UPI PINs, or net-banking credentials."},{"heading":"5. Trusted Data Processors & Logistics Partners","body":"We never sell, rent, or trade client personal data. We share strictly limited operational fields solely with vetted processors bound by confidentiality agreements: payment gateways (Razorpay, Cashfree) for payment authorization and refunds; domestic and international courier partners (Shiprocket, Blue Dart, DHL Express, FedEx) for insured delivery and customs clearance; transactional email infrastructure (Resend) for OTP codes and order milestones; and Cloudflare edge infrastructure for DDoS mitigation and encrypted database storage."},{"heading":"6. International Cross-Border Data Transfers","body":"Because DEYNOLD DANNY serves global patrons across India, North America, Europe, the Middle East, and Asia-Pacific, your data may be processed on encrypted Cloudflare global edge nodes and transferred to destination customs authorities solely to clear international deliveries. All cross-border transfers adhere to DPDP Act Section 16 notifications and EU Standard Contractual Clauses (SCCs) with TLS 1.3 encryption in transit."},{"heading":"7. Data Retention & Statutory Archival","body":"Account profiles and saved addresses are retained while your client account remains active. One-time verification codes expire within 10 minutes and are purged automatically. Order invoices, tax ledgers, and payment audit logs are retained for the statutory period mandated under Indian GST and Companies Act regulations (typically 8 financial years), after which personal identifiers are anonymized or destroyed."},{"heading":"8. Your Rights as a Data Principal / Client","body":"Under the DPDP Act 2023, GDPR, and CCPA, you hold the right to: (a) Access & Portability — export a complete machine-readable JSON archive of your account data directly from your Private Client Portal; (b) Correction & Updating — update inaccurate profile or address information at any time; (c) Erasure & Anonymization — request permanent account erasure/anonymization directly inside your Account Portal (once no active unfulfilled orders or open disputes remain); (d) Withdraw Consent — adjust cookie, analytics, or newsletter permissions at any time with zero service penalty; (e) Nominate — designate a representative under DPDP Section 14 to exercise your rights in the event of incapacity."},{"heading":"9. Protection of Minors","body":"Our digital flagship is intended exclusively for individuals aged 18 years or older (or the age of legal majority in your jurisdiction). We do not knowingly collect personal data from children under 18. If a parent or guardian believes a minor has provided personal information, contact our Data Protection Officer immediately for prompt deletion."},{"heading":"10. Data Protection & Grievance Redressal Officer","body":"In compliance with the DPDP Act 2023 and the Consumer Protection (E-Commerce) Rules, 2020, any privacy inquiry, data request, or grievance may be addressed to our Data Protection & Grievance Officer: Email: privacy@deynolddanny.com | Concierge Desk: +91 11 4820 9000 (Mon–Sat, 10:00–19:00 IST) | Address: DEYNOLD DANNY Atelier Pvt. Ltd., New Delhi, India. All grievances are acknowledged within 48 hours and resolved within 30 calendar days."}]}',
