-- 3. Upgrade Shipping, Returns, Exchanges & Refund Policy
UPDATE cms_sections
SET
  draft_props_json = '{"eyebrow":"GLOBAL LOGISTICS, RETURNS & REFUNDS","heading":"Shipping, Returns & Refund Policy","effectiveDate":"Effective: November 2026 · Domestic India & Worldwide Express Dispatch","sections":[{"heading":"1. Atelier Preparation & Dispatch Timelines","body":"Every ready-to-wear order undergoes multi-point atelier quality inspection, steam finishing, and signature archival boxing before dispatch from our New Delhi studio. Orders verified before 14:00 IST (Monday–Saturday) are dispatched within 24–48 business hours. Customized, altered, or made-to-order pieces require 7–14 business days of tailoring prior to shipment."},{"heading":"2. Domestic Delivery Across India","body":"Orders across India above our complimentary shipping threshold (currently ₹5,000, configurable in real time at checkout) enjoy complimentary insured air-express delivery via Shiprocket / Blue Dart Apex / Delhivery Air. Metro deliveries arrive within 2–4 business days; Tier-2/3 PIN codes arrive within 4–6 business days. Full transit insurance protects every consignment until signed hand-delivery."},{"heading":"3. International Express Delivery (12+ Global Markets)","body":"DEYNOLD DANNY ships insured air express via DHL Express and FedEx International Priority to the United States, United Kingdom, European Union, United Arab Emirates, Singapore, Australia, Canada, Switzerland, Japan, Saudi Arabia, Qatar, and select global destinations. Typical international transit is 3–7 business days from dispatch, with end-to-end AWB tracking emailed automatically."},{"heading":"4. International Customs Duties, Import VAT & Taxes","body":"Unless explicitly stated as Delivered Duty Paid (DDP) at checkout, international shipments are dispatched on a Delivered Duty Unpaid (DDU / DAP) basis. Local import duties, customs clearance fees, and destination VAT/GST levied by the receiving country''s customs authority are payable by the recipient directly to the courier prior to final delivery. Refusal to pay statutory import duties may result in return-to-origin freight and customs charges being deducted from any eligible refund."},{"heading":"5. Signature Archival Presentation","body":"Each piece arrives enclosed in a rigid FSC-certified DEYNOLD DANNY magnetic keepsake box, layered in acid-free archival tissue, accompanied by a contoured cedar-tone coat hanger (for tailored outerwear and suiting), breathable cotton garment cover, and a tamper-evident Atelier Authenticity Tag."},{"heading":"6. Order Cancellation Window","body":"Clients may cancel an unshipped order directly inside the Private Client Portal (Account > Orders) or by contacting concierge@deynolddanny.com prior to courier handover/AWB generation. Once an order is cancelled prior to dispatch, 100% of the paid amount is refunded automatically to the original payment instrument within 5–7 business days."},{"heading":"7. 14-Day Returns & Size Exchanges","body":"Eligible ready-to-wear garments may be returned for a refund or exchanged for an alternate size within 14 calendar days of recorded delivery. To qualify: (a) garments must be completely unworn, unwashed, unaltered, and free of perfume, makeup, or odour; (b) the tamper-evident Atelier Authenticity Tag and original hangtags must remain attached; and (c) all original presentation boxes, hangers, dust bags, and invoice documentation must be included."},{"heading":"8. Non-Returnable & Final-Sale Items","body":"For hygiene and bespoke craftsmanship reasons, the following items are final sale and ineligible for return unless received damaged or defective: bespoke or made-to-measure commissions, garments altered to client specifications, monogrammed pieces, intimate apparel, fragrances with broken seals, and items explicitly marked Archive / Final Sale at purchase."},{"heading":"9. Return Inspection & Refund Timelines","body":"For domestic Indian orders, DEYNOLD DANNY arranges complimentary insured reverse pickup via Shiprocket within 48 hours of return approval. International patrons receive a prepaid DHL Express return waybill (international return courier fees and original non-refundable customs duties may apply unless the item is defective). Upon arrival at our New Delhi atelier, garments pass quality inspection within 2–3 business days. Approved refunds are issued strictly to the original payment source (Razorpay UPI, credit/debit card, net banking, or wallet) and reflect within 5–7 business days depending on your issuing bank."},{"heading":"10. Damaged, Defective, or Incorrect Delivery","body":"In the rare event a parcel arrives visibly tampered, damaged in transit, or contains an incorrect garment, please photograph the outer carton, shipping label, and garment within 48 hours of delivery and email returns@deynolddanny.com quoting your order reference. We prioritize an immediate complimentary replacement or full refund including all shipping charges."}]}',
  published_props_json = '{"eyebrow":"GLOBAL LOGISTICS, RETURNS & REFUNDS","heading":"Shipping, Returns & Refund Policy","effectiveDate":"Effective: November 2026 · Domestic India & Worldwide Express Dispatch","sections":[{"heading":"1. Atelier Preparation & Dispatch Timelines","body":"Every ready-to-wear order undergoes multi-point atelier quality inspection, steam finishing, and signature archival boxing before dispatch from our New Delhi studio. Orders verified before 14:00 IST (Monday–Saturday) are dispatched within 24–48 business hours. Customized, altered, or made-to-order pieces require 7–14 business days of tailoring prior to shipment."},{"heading":"2. Domestic Delivery Across India","body":"Orders across India above our complimentary shipping threshold (currently ₹5,000, configurable in real time at checkout) enjoy complimentary insured air-express delivery via Shiprocket / Blue Dart Apex / Delhivery Air. Metro deliveries arrive within 2–4 business days; Tier-2/3 PIN codes arrive within 4–6 business days. Full transit insurance protects every consignment until signed hand-delivery."},{"heading":"3. International Express Delivery (12+ Global Markets)","body":"DEYNOLD DANNY ships insured air express via DHL Express and FedEx International Priority to the United States, United Kingdom, European Union, United Arab Emirates, Singapore, Australia, Canada, Switzerland, Japan, Saudi Arabia, Qatar, and select global destinations. Typical international transit is 3–7 business days from dispatch, with end-to-end AWB tracking emailed automatically."},{"heading":"4. International Customs Duties, Import VAT & Taxes","body":"Unless explicitly stated as Delivered Duty Paid (DDP) at checkout, international shipments are dispatched on a Delivered Duty Unpaid (DDU / DAP) basis. Local import duties, customs clearance fees, and destination VAT/GST levied by the receiving country''s customs authority are payable by the recipient directly to the courier prior to final delivery. Refusal to pay statutory import duties may result in return-to-origin freight and customs charges being deducted from any eligible refund."},{"heading":"5. Signature Archival Presentation","body":"Each piece arrives enclosed in a rigid FSC-certified DEYNOLD DANNY magnetic keepsake box, layered in acid-free archival tissue, accompanied by a contoured cedar-tone coat hanger (for tailored outerwear and suiting), breathable cotton garment cover, and a tamper-evident Atelier Authenticity Tag."},{"heading":"6. Order Cancellation Window","body":"Clients may cancel an unshipped order directly inside the Private Client Portal (Account > Orders) or by contacting concierge@deynolddanny.com prior to courier handover/AWB generation. Once an order is cancelled prior to dispatch, 100% of the paid amount is refunded automatically to the original payment instrument within 5–7 business days."},{"heading":"7. 14-Day Returns & Size Exchanges","body":"Eligible ready-to-wear garments may be returned for a refund or exchanged for an alternate size within 14 calendar days of recorded delivery. To qualify: (a) garments must be completely unworn, unwashed, unaltered, and free of perfume, makeup, or odour; (b) the tamper-evident Atelier Authenticity Tag and original hangtags must remain attached; and (c) all original presentation boxes, hangers, dust bags, and invoice documentation must be included."},{"heading":"8. Non-Returnable & Final-Sale Items","body":"For hygiene and bespoke craftsmanship reasons, the following items are final sale and ineligible for return unless received damaged or defective: bespoke or made-to-measure commissions, garments altered to client specifications, monogrammed pieces, intimate apparel, fragrances with broken seals, and items explicitly marked Archive / Final Sale at purchase."},{"heading":"9. Return Inspection & Refund Timelines","body":"For domestic Indian orders, DEYNOLD DANNY arranges complimentary insured reverse pickup via Shiprocket within 48 hours of return approval. International patrons receive a prepaid DHL Express return waybill (international return courier fees and original non-refundable customs duties may apply unless the item is defective). Upon arrival at our New Delhi atelier, garments pass quality inspection within 2–3 business days. Approved refunds are issued strictly to the original payment source (Razorpay UPI, credit/debit card, net banking, or wallet) and reflect within 5–7 business days depending on your issuing bank."},{"heading":"10. Damaged, Defective, or Incorrect Delivery","body":"In the rare event a parcel arrives visibly tampered, damaged in transit, or contains an incorrect garment, please photograph the outer carton, shipping label, and garment within 48 hours of delivery and email returns@deynolddanny.com quoting your order reference. We prioritize an immediate complimentary replacement or full refund including all shipping charges."}]}',
  updated_at = datetime('now')
WHERE id = 'sec_legal_shipping_body';

-- 4. Upgrade Terms & Conditions (Consumer Protection E-Commerce Rules 2020 + Multi-Currency + GST)
UPDATE cms_sections
SET
  draft_props_json = '{"eyebrow":"ATELIER TERMS OF SALE & GOVERNANCE","heading":"Terms & Conditions of Sale","effectiveDate":"Effective: November 2026 · Governed by the Laws of India","sections":[{"heading":"1. Legal Entity & Statutory Disclosures","body":"This digital flagship is owned and operated by DEYNOLD DANNY Atelier Pvt. Ltd., New Delhi, India (\"DEYNOLD DANNY\", \"we\", \"our\"). In accordance with the Consumer Protection (E-Commerce) Rules, 2020 and the Information Technology Act, 2000, every garment sold on this storefront is crafted in India unless an explicit alternate country of origin is noted on the product specification sheet."},{"heading":"2. Acceptance & Eligibility","body":"By accessing our digital flagship, creating a Private Client account, or placing an order, you confirm that you are at least 18 years of age, possess legal capacity to enter binding contracts, and accept these Terms alongside our Privacy Policy, Cookie Policy, and Shipping & Returns Policy."},{"heading":"3. Artisanal Craftsmanship & Natural Fibers","body":"DEYNOLD DANNY creations are crafted from noble natural textiles—virgin wool, inner-fleece cashmere, long-staple cotton, mulberry silk, and full-grain calfskin. Subtle variations in yarn grain, weave character, or hand-burnished patina are inherent hallmarks of authentic artisanal manufacture rather than defects. Screen color calibration may vary slightly across devices."},{"heading":"4. Multi-Currency Display & Authoritative INR Settlement","body":"To assist international patrons across the US, UK, EU, UAE, Singapore, Australia, Canada, Switzerland, Japan, Saudi Arabia, and Qatar, our storefront offers live indicative currency conversion refreshed automatically against daily foreign-exchange reference rates. All product prices, discounts, taxes, and payment authorizations are authoritatively calculated and settled in Indian Rupees (INR ₹) on our server. Your card issuer or bank determines the final billing-statement conversion rate and any foreign transaction fee."},{"heading":"5. GST Pricing, Statutory Invoicing & Payment Guardrails","body":"Domestic Indian prices are inclusive of applicable Goods & Services Tax (GST) unless explicitly stated otherwise, and a compliant GST tax invoice is generated inside your Private Client Portal. Orders via UPI are subject to statutory RBI transaction limits; orders exceeding statutory Indian Income Tax thresholds may require Permanent Account Number (PAN) verification prior to dispatch."},{"heading":"6. Inventory Allocation & Order Acceptance","body":"Adding an item to your shopping bag temporarily holds stock during checkout, but a binding contract of sale is formed strictly upon: (a) cryptographic payment capture verified by our backend via Razorpay or Cashfree; and (b) dispatch confirmation from our atelier. We reserve the right to decline or cancel any order—with an immediate 100% refund—in the event of pricing error, stock discrepancy, courier non-serviceability, or suspected payment fraud."},{"heading":"7. Promotional Codes & Private Client Benefits","body":"Promotional codes are single-use unless explicitly specified, cannot be combined with other offers, carry minimum-spend and expiry rules validated strictly on our server, and have no cash redemption value. Abuse or automated scraping of promotional codes voids eligibility."},{"heading":"8. Account Integrity & Prohibited Conduct","body":"You are responsible for safeguarding access to your registered email inbox used for passwordless OTP authentication. Automated scraping, inventory hoarding bots, reverse-engineering of APIs, fraudulent chargebacks, or unauthorized commercial resale of DEYNOLD DANNY garments are strictly prohibited and may result in permanent account suspension."},{"heading":"9. Intellectual Property","body":"All garment silhouettes, lookbook photography, typography, the DEYNOLD DANNY wordmark and anchor monogram, copywriting, and software architecture are the exclusive intellectual property of DEYNOLD DANNY Atelier Pvt. Ltd., protected under Indian copyright, trademark, and international treaties. No material may be copied, mirrored, or reproduced without written authorization."},{"heading":"10. Limitation of Liability & Force Majeure","body":"To the maximum extent permitted by applicable law, DEYNOLD DANNY''s aggregate liability arising from any order shall not exceed the actual purchase price paid for the specific garment in question. Neither party shall be liable for delays caused by Force Majeure events including natural disasters, customs strikes, airspace closures, pandemics, or governmental directives."},{"heading":"11. Governing Law, Jurisdiction & Statutory Grievance Officer","body":"These Terms are governed by the laws of India, without regard to conflict-of-law principles, and subject to the exclusive jurisdiction of competent courts in New Delhi, India (without prejudice to mandatory non-waivable statutory consumer rights in your home jurisdiction). Statutory Grievance Officer (Consumer Protection Rules 2020): grievance@deynolddanny.com | +91 11 4820 9000 (Mon–Sat, 10:00–19:00 IST). Complaints are acknowledged within 48 hours and resolved within 30 days."}]}',
  published_props_json = '{"eyebrow":"ATELIER TERMS OF SALE & GOVERNANCE","heading":"Terms & Conditions of Sale","effectiveDate":"Effective: November 2026 · Governed by the Laws of India","sections":[{"heading":"1. Legal Entity & Statutory Disclosures","body":"This digital flagship is owned and operated by DEYNOLD DANNY Atelier Pvt. Ltd., New Delhi, India (\"DEYNOLD DANNY\", \"we\", \"our\"). In accordance with the Consumer Protection (E-Commerce) Rules, 2020 and the Information Technology Act, 2000, every garment sold on this storefront is crafted in India unless an explicit alternate country of origin is noted on the product specification sheet."},{"heading":"2. Acceptance & Eligibility","body":"By accessing our digital flagship, creating a Private Client account, or placing an order, you confirm that you are at least 18 years of age, possess legal capacity to enter binding contracts, and accept these Terms alongside our Privacy Policy, Cookie Policy, and Shipping & Returns Policy."},{"heading":"3. Artisanal Craftsmanship & Natural Fibers","body":"DEYNOLD DANNY creations are crafted from noble natural textiles—virgin wool, inner-fleece cashmere, long-staple cotton, mulberry silk, and full-grain calfskin. Subtle variations in yarn grain, weave character, or hand-burnished patina are inherent hallmarks of authentic artisanal manufacture rather than defects. Screen color calibration may vary slightly across devices."},{"heading":"4. Multi-Currency Display & Authoritative INR Settlement","body":"To assist international patrons across the US, UK, EU, UAE, Singapore, Australia, Canada, Switzerland, Japan, Saudi Arabia, and Qatar, our storefront offers live indicative currency conversion refreshed automatically against daily foreign-exchange reference rates. All product prices, discounts, taxes, and payment authorizations are authoritatively calculated and settled in Indian Rupees (INR ₹) on our server. Your card issuer or bank determines the final billing-statement conversion rate and any foreign transaction fee."},{"heading":"5. GST Pricing, Statutory Invoicing & Payment Guardrails","body":"Domestic Indian prices are inclusive of applicable Goods & Services Tax (GST) unless explicitly stated otherwise, and a compliant GST tax invoice is generated inside your Private Client Portal. Orders via UPI are subject to statutory RBI transaction limits; orders exceeding statutory Indian Income Tax thresholds may require Permanent Account Number (PAN) verification prior to dispatch."},{"heading":"6. Inventory Allocation & Order Acceptance","body":"Adding an item to your shopping bag temporarily holds stock during checkout, but a binding contract of sale is formed strictly upon: (a) cryptographic payment capture verified by our backend via Razorpay or Cashfree; and (b) dispatch confirmation from our atelier. We reserve the right to decline or cancel any order—with an immediate 100% refund—in the event of pricing error, stock discrepancy, courier non-serviceability, or suspected payment fraud."},{"heading":"7. Promotional Codes & Private Client Benefits","body":"Promotional codes are single-use unless explicitly specified, cannot be combined with other offers, carry minimum-spend and expiry rules validated strictly on our server, and have no cash redemption value. Abuse or automated scraping of promotional codes voids eligibility."},{"heading":"8. Account Integrity & Prohibited Conduct","body":"You are responsible for safeguarding access to your registered email inbox used for passwordless OTP authentication. Automated scraping, inventory hoarding bots, reverse-engineering of APIs, fraudulent chargebacks, or unauthorized commercial resale of DEYNOLD DANNY garments are strictly prohibited and may result in permanent account suspension."},{"heading":"9. Intellectual Property","body":"All garment silhouettes, lookbook photography, typography, the DEYNOLD DANNY wordmark and anchor monogram, copywriting, and software architecture are the exclusive intellectual property of DEYNOLD DANNY Atelier Pvt. Ltd., protected under Indian copyright, trademark, and international treaties. No material may be copied, mirrored, or reproduced without written authorization."},{"heading":"10. Limitation of Liability & Force Majeure","body":"To the maximum extent permitted by applicable law, DEYNOLD DANNY''s aggregate liability arising from any order shall not exceed the actual purchase price paid for the specific garment in question. Neither party shall be liable for delays caused by Force Majeure events including natural disasters, customs strikes, airspace closures, pandemics, or governmental directives."},{"heading":"11. Governing Law, Jurisdiction & Statutory Grievance Officer","body":"These Terms are governed by the laws of India, without regard to conflict-of-law principles, and subject to the exclusive jurisdiction of competent courts in New Delhi, India (without prejudice to mandatory non-waivable statutory consumer rights in your home jurisdiction). Statutory Grievance Officer (Consumer Protection Rules 2020): grievance@deynolddanny.com | +91 11 4820 9000 (Mon–Sat, 10:00–19:00 IST). Complaints are acknowledged within 48 hours and resolved within 30 days."}]}',
  updated_at = datetime('now')
WHERE id = 'sec_legal_terms_body';

-- 5. Upgrade Cookie Policy
UPDATE cms_sections
SET
  draft_props_json = '{"eyebrow":"DIGITAL PRIVACY & CONSENT GOVERNANCE","heading":"Cookie & Storage Policy","effectiveDate":"Effective: November 2026 · Privacy-by-Default Architecture","sections":[{"heading":"1. Privacy-by-Default Architecture","body":"DEYNOLD DANNY operates a strict fail-closed consent architecture. Non-essential analytics and marketing telemetry are disabled by default until you explicitly opt in via our Cookie Governance Banner. We never load third-party ad-retargeting trackers without your affirmative consent."},{"heading":"2. Strictly Necessary Cookies & Security Storage","body":"These mechanisms are essential for site security, session integrity, and checkout reliability and cannot be disabled: (a) dd_refresh_token (HttpOnly, Secure, SameSite cookie) — maintains authenticated passwordless sessions without exposing credentials to browser JavaScript; (b) dd_session_id (session preference) — binds anonymous shopping bags to our server cart engine; (c) dd_consent_v1 — records your exact DPDP/GDPR consent choices."},{"heading":"3. Functional Client Preferences","body":"Stored locally in your browser solely to personalize browsing without tracking you across external sites: (a) dd_region_currency — remembers your chosen country and display currency (e.g. INR, USD, GBP, EUR, AED); (b) dd_wishlist — preserves your curated wishlist pieces between visits."},{"heading":"4. Optional Analytics & Personalization (Opt-In Only)","body":"Only when you explicitly select Accept All or enable Analytics in Cookie Preferences do we record anonymized first-party storefront telemetry (such as page views and collection interest) to improve garment sizing, navigation clarity, and inventory planning."},{"heading":"5. Managing or Withdrawing Consent","body":"You may inspect, modify, or withdraw optional cookie permissions at any time using the Cookie Preferences link in the site footer or via your browser privacy settings. Withdrawing optional consent never restricts your ability to browse, purchase, or manage orders."}]}',
  published_props_json = '{"eyebrow":"DIGITAL PRIVACY & CONSENT GOVERNANCE","heading":"Cookie & Storage Policy","effectiveDate":"Effective: November 2026 · Privacy-by-Default Architecture","sections":[{"heading":"1. Privacy-by-Default Architecture","body":"DEYNOLD DANNY operates a strict fail-closed consent architecture. Non-essential analytics and marketing telemetry are disabled by default until you explicitly opt in via our Cookie Governance Banner. We never load third-party ad-retargeting trackers without your affirmative consent."},{"heading":"2. Strictly Necessary Cookies & Security Storage","body":"These mechanisms are essential for site security, session integrity, and checkout reliability and cannot be disabled: (a) dd_refresh_token (HttpOnly, Secure, SameSite cookie) — maintains authenticated passwordless sessions without exposing credentials to browser JavaScript; (b) dd_session_id (session preference) — binds anonymous shopping bags to our server cart engine; (c) dd_consent_v1 — records your exact DPDP/GDPR consent choices."},{"heading":"3. Functional Client Preferences","body":"Stored locally in your browser solely to personalize browsing without tracking you across external sites: (a) dd_region_currency — remembers your chosen country and display currency (e.g. INR, USD, GBP, EUR, AED); (b) dd_wishlist — preserves your curated wishlist pieces between visits."},{"heading":"4. Optional Analytics & Personalization (Opt-In Only)","body":"Only when you explicitly select Accept All or enable Analytics in Cookie Preferences do we record anonymized first-party storefront telemetry (such as page views and collection interest) to improve garment sizing, navigation clarity, and inventory planning."},{"heading":"5. Managing or Withdrawing Consent","body":"You may inspect, modify, or withdraw optional cookie permissions at any time using the Cookie Preferences link in the site footer or via your browser privacy settings. Withdrawing optional consent never restricts your ability to browse, purchase, or manage orders."}]}',
  updated_at = datetime('now')
WHERE id = 'sec_legal_cookie_body';
